import{_ as l,W as e,X as a,a1 as r}from"./framework-af1ddc77.js";const t={};function d(n,i){return e(),a("div",null,[...i[0]||(i[0]=[r('<h1 id="校园技巧" tabindex="-1"><a class="header-anchor" href="#校园技巧" aria-hidden="true">#</a> 校园技巧</h1><h2 id="生活" tabindex="-1"><a class="header-anchor" href="#生活" aria-hidden="true">#</a> 生活</h2><ul><li>床帘早买早受益，提高睡眠质量，提供一个隐私的空间。(军训期间不让挂)（2026年军训的要求是床帘可以拉开看到床上情况即可）</li><li>如果室友晚上太吵，可以买个隔音耳罩。</li><li>错峰一个人洗澡真的很爽。</li><li>照澜院那边水果比C楼猫超便宜。</li><li>尽早谈恋爱有益身心健康，单身太久容易出事。</li><li>对于大部分理工类同学，买windows电脑可以减少很多麻烦。</li><li>自行车自己在网上买，质量有保证（宿舍楼下卖的自行车都是翻新车，三天两头出问题）（山地车还行，普通的质量确实一般）</li><li>多参加各种经验分享会，有助于适应大学生活，变得更有规划</li></ul><h2 id="学习" tabindex="-1"><a class="header-anchor" href="#学习" aria-hidden="true">#</a> 学习</h2><ul><li>选课期间可以关注各个院系的学生会推送，他们往往会整理一些课程测评出来</li><li>往年题考试前一定要做，考试重复率一般可达10%-70%</li><li>不要急于表现自己牛逼而提前选一大堆硬课，按照培养方案来把GPA刷高才是王道</li><li>GPA重要，但也仅限于本科阶段的评优和保研。如果你不care外界对你的“排名”“评优”，那么GPA没有任何用（想想你的小学成绩现在还有用吗）</li><li>如果想保研，建议最迟大三上学期联系老师进入实验室打杂。如果不打算读研，科研并不重要，请尽早实习。</li><li>双学位会占用周末时间上课，并且要多写一个毕业设计。</li><li>辅修每学期会多上2门左右的课程。</li><li>很多教材看电子版足够了，没必要买纸质版，C楼教材中心有大量二手书也可以购买。</li><li>金蝉脱壳：在作业提交日期截止前还没写完，可以先提交一个“网盘链接”，后面再把作业传到网盘链接里。该方法成功的前提是助教不会立即去网络学堂收作业，因此给自己多了一个缓冲的机会。</li></ul><hr><p><em>上次修改时间：2026-9-5</em><em>贡献者：数41施计芸，计76林慎吾，自76张广昱，法32于大虾</em></p>',7)])])}const c=l(t,[["render",d],["__file","jiqiao.html.vue"]]);export{c as default};
